class Worker:
    """A generic worker at the forge."""

    def __init__(self, name, shift_hours):
        self.name = name
        self.shift_hours = shift_hours

    def clock_in(self):
        print(f"{self.name} clocks in for a {self.shift_hours}-hour shift.")


class Smith(Worker):
    """A worker who specializes in smithing."""

    def __init__(self, name, shift_hours, specialty):
        super().__init__(name, shift_hours)
        self.specialty = specialty

    def clock_in(self):
        print(f"{self.name} clocks in to work on {self.specialty}.")

    def forge_item(self, item):
        print(f"{self.name} forges a {item}.")


apprentice = Smith("Rin", 6, "blades")
apprentice.clock_in()
apprentice.forge_item("dagger")

