assignment.solutionCode:
class Guard:
    def __init__(self, name, post):
        self.name = name
        self.post = post

    def report(self):
        print(f"{self.name} is stationed at {self.post}.")


class Sentinel(Guard):
    def __init__(self, name, post, alert_level):
        super().__init__(name, post)
        self.alert_level = alert_level

    def report(self):
        print(f"{self.name} is stationed at {self.post} (alert level: {self.alert_level}).")

    def sound_alarm(self):
        print(f"{self.name} sounds the alarm!")


watcher = Sentinel("Orin", "north wall", "yellow")
watcher.report()
watcher.sound_alarm()
